import{_ as t,o as e,a,b as r}from"./app.C41L12d5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"协作组","link":"/api/SIMT-API/cooperative_groups/cooperative_groups"},{"text":"协作组简介","link":"/api/SIMT-API/cooperative_groups/cooperative_groups_intro"}]},"headers":[],"relativePath":"api/SIMT-API/cooperative_groups/cooperative_groups_intro.md","filePath":"api/SIMT-API/cooperative_groups/cooperative_groups_intro.md","lastUpdated":1788506723000}'),i={name:"api/SIMT-API/cooperative_groups/cooperative_groups_intro.md"};function l(p,o,_,c,s,d){return e(),a("div",null,[...o[0]||(o[0]=[r('<div><article class="markdown-body"><h1>协作组简介</h1><p>协作组（cooperative groups）是Ascend C SIMT编程模型的一种扩展，用于组织协作线程组。通过协作组能够更细粒度地管理线程，从而实现更高效的线程并行协作。</p><p>当前提供的协作组类型有：</p><ul><li><a href="thread_block/thread_block_intro.html">thread_block</a>：对线程块的抽象，提供统一的线程管理接口。</li><li><a href="coalesced_group/coalesced_group_intro.html">coalesced_group</a>：Warp中的活跃线程集合。</li><li><a href="thread_block_tile/thread_block_tile_intro.html">thread_block_tile</a>：手动划分出的线程子组。</li><li><a href="grid_group/grid_group_intro.html">grid_group</a>：对一个核函数（Kernel）启动的所有SIMT线程的抽象，提供跨线程块的查询和同步接口。</li></ul><p>基于以上协作组类型，提供以下划分操作，支持将一个协作组划分为多个子组：</p><ul><li><a href="tiled_partition.html">tiled_partition</a>：将父组划分成指定大小的子组。</li><li><a href="binary_partition.html">binary_partition</a>：根据自定义的0、1标签将父组划分为两个子组。</li></ul><p>基于以上协作组类型，提供以下通用操作：</p><ul><li><a href="sync.html">sync</a>：同步指定协作组内的所有线程，功能等价于调用该协作组对象的成员函数<code>sync()</code>。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>所有协作组API均在<code>cooperative_groups</code>命名空间下，调用时需添加命名空间。<br><code>grid_group</code>仅支持SIMT编程场景，不支持SIMD与SIMT混合编程场景。</p></div></article></div>',1)])])}const h=t(i,[["render",l]]);export{u as __pageData,h as default};
